 SELECT gen_random_uuid(),source_id,'GET','/sru',0.047259,true,3600,'Search official Dutch notices by title, publishing authority and publication date; retrieve an identified notice. Includes historical applications and decisions. An application is not an issued permit. One bounded page per purchase.','{"type":"object","properties":{"q":{"type":"string","minLength":1,"maxLength":200,"required":false,"description":"Literal Dutch words to match in an official publication title. Not a CQL expression.","x-parameter-location":"query"},"authority":{"type":"string","minLength":1,"maxLength":200,"required":false,"description":"Exact publishing authority, e.g. Amsterdam.","x-parameter-location":"query"},"from":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$","required":false,"description":"Inclusive publication date from, YYYY-MM-DD.","x-parameter-location":"query"},"until":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}$","required":false,"description":"Inclusive publication date until, YYYY-MM-DD.","x-parameter-location":"query"},"start":{"type":"integer","minimum":1,"maximum":100000,"required":false,"description":"One-based start record from next_start in a saved KOOP page.","x-parameter-location":"query"},"publication_id":{"type":"string","pattern":"^[A-Za-z0-9-]{1,100}$","required":false,"description":"Exact official publication identifier from a search result, e.g. gmb-2026-427235.","x-parameter-location":"query"},"limit":{"type":"integer","minimum":1,"maximum":25,"default":10,"x-parameter-location":"query"}}}'::jsonb,'{"type":"object","required":["items","coverage","notice","source_url"],"properties":{"items":{"type":"array","items":{"type":"object"}},"coverage":{"type":"object","required":["complete","scope"],"properties":{"complete":{"type":"boolean"},"scope":{"type":"string"}}},"notice":{"type":"string"},"source_url":{"type":"string"}}}'::jsonb,'{"q":"omgevingsvergunning","authority":"Amsterdam","from":"2026-09-01","until":"2026-09-11"}'::jsonb,'{"coverage":{"complete":false,"scope":"Official publication title search; sorted by modification date. Not consolidated current law."},"items":[{"authority":"Amsterdam","id":"gmb-2026-427235","modified":"2026-09-11","publication":"Gemeenteblad","published":"2026-09-11","summary":"toevoegen van een vloer, wijzigen indeling en brandcompartimentering,  en toevoegen woning","title":"Aanvraag omgevingsvergunning Tan Malakastraat 80 1087WE Amsterdam","type":"omgevingsvergunning","url":"https://zoek.officielebekendmakingen.nl/gmb-2026-427235.html"},{"authority":"Amsterdam","id":"gmb-2026-428658","modified":"2026-09-11","publication":"Gemeenteblad","published":"2026-09-11","summary":"veranderen en vergroten van de woning d.m.v. een dakopbouw","title":"Aanvraag omgevingsvergunning Kantershof 574 1104HG Amsterdam","type":"omgevingsvergunning","url":"https://zoek.officielebekendmakingen.nl/gmb-2026-428658.html"}],"next_start":3,"notice":"An application notice is not an issued permit. Company-name mentions do not establish identity or a complete permit history.","query":{"authority":"Amsterdam","limit":"2","q":"omgevingsvergunning"},"source_url":"https://repository.overheid.nl/sru?operation=searchRetrieve&version=2.0&httpAccept=application%2Fjson&query=c.product-area%3D%3Dofficielepublicaties+AND+dt.title%3D%22omgevingsvergunning%22+AND+dt.creator%3D%3D%22Amsterdam%22+sortBy+dt.modified%2Fsort.descending&startRecord=1&maximumRecords=2","start":1,"total":101939}'::jsonb,ARRAY['KOOP','overheid.nl','bekendmakingen','vergunningen','official notices','permits','municipal decisions'],ARRAY['Government and public data','Real estate'],ARRAY['Search official Dutch notices by title, publishing authority and publication date; retrieve an identified notice. Includes historical applications and decisions. An application is not an issued permit. One bounded page per purchase.'],'data','lookup',true,'https://www.koopoverheid.nl/binaries/koop/documenten/instructies/2021/02/09/handleiding-voor-het-uitvragen-van-de-collectie-officiele-publicaties/HandleidingSRU2.0.pdf','Search official Dutch notices by title, publishing authority and publication date; retrieve an identified notice. Includes historical applications and decisions. An application is not an issued permit. One bounded page per purchase.','provider_documentation_and_live_probe',1
