 SELECT gen_random_uuid(),source_id,'GET','/api/v1/opendata/subsidies',0.047259,true,3600,'Keyword discovery within the first 50 public RVO subsidy descriptions only. Includes historical schemes. Later-page access is unverified; no-match does not mean no subsidy exists. Current application status, deadlines and eligibility are unknown.','{"type":"object","properties":{"q":{"type":"string","minLength":1,"maxLength":200,"required":true,"description":"Literal keyword, searched only within the first 50 public RVO descriptions. No complete-catalog, application-status or eligibility claim.","x-parameter-location":"query"},"sector":{"type":"string","minLength":1,"maxLength":200,"required":false,"description":"Exact sector label from RVO source descriptions.","x-parameter-location":"query"},"audience":{"type":"string","minLength":1,"maxLength":200,"required":false,"description":"Exact audience label from RVO source descriptions.","x-parameter-location":"query"}},"required":["q"]}'::jsonb,'{"type":"object","required":["items","coverage","notice","source_url"],"properties":{"items":{"type":"array","items":{"type":"object"}},"coverage":{"type":"object","required":["complete","scope"],"properties":{"complete":{"type":"boolean"},"scope":{"type":"string"}}},"notice":{"type":"string"},"source_url":{"type":"string"}}}'::jsonb,'{"q":"energie"}'::jsonb,'{"coverage":{"complete":false,"scope":"Keyword matches within the first public RVO page only (at most 50 descriptions). Later pages are not verified."},"items":[{"application_status":"unknown","audiences":["MKB (ook zzp)","School / Kennisinstelling"],"description":"De Transitiefaciliteit (TF) stimuleerde Nederlandse mkb-bedrijven en kennisinstellingen om actief te worden op de veelbelovende markten Colombia, Vietnam en Zuid-Afrika. Het doel van het programma was om het ondernemingsklimaat in deze landen te verbeteren en de omvang van de handel, investeringen en diensten door Nederlandse bedrijven te vergroten.","eligibility":"not_assessed","id":"89c4fee3-4683-4916-b7f7-50c6e3d7b3b7","modified":"2025-04-16T11:00:57+00:00","sectors":["Energiesector","Vervoer en logistiek","Watersector"],"subjects":["Internationaal ondernemen","Ontwikkelingssamenwerking"],"title":"Transitiefaciliteit (TF)","url":"https://www.rvo.nl/subsidies-financiering/transitiefaciliteit-tf"},{"application_status":"unknown","audiences":["Financier","MKB (ook zzp)","Agrarisch ondernemer"],"description":"Heeft u als ondernemer te weinig onderpand om geld te lenen? Informeer bij uw financier naar de mogelijkheden van de Borgstelling MKB-kredieten (BMKB). De BMKB vergroot het onderpand en daarmee ook de financierbaarheid van de onderneming, ook in de toekomst.&nbsp;Om de financieringsmogelijkheden voor verduurzamingsinvesteringen door het mkb te vergroten is de BMKB verruimd met een groen luik, de BMKB-G.","eligibility":"not_assessed","id":"530035f0-7833-448f-adee-a36988bc6dc7","modified":"2026-03-13T09:30:11+00:00","sectors":["Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting","Agrarische sector"],"subjects":["Innovatie, onderzoek en onderwijs"],"title":"Borgstelling MKB-kredieten (BMKB)","url":"https://www.rvo.nl/subsidies-financiering/bmkb"},{"application_status":"unknown","audiences":["Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)","Producentenorganisatie","School / Kennisinstelling"],"description":"Samen staat u sterker. Daarom brengt Partners for International Business (PIB) private en publieke partijen bij elkaar om gezamenlijk een nieuwe markt te betreden.&nbsp;Uw aanvraag direct regelen&nbsp;","eligibility":"not_assessed","id":"f379965a-8b88-445b-bd06-657a5c555bca","modified":"2026-04-13T08:51:29+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Internationaal ondernemen"],"title":"Partners for International Business (PIB)","url":"https://www.rvo.nl/subsidies-financiering/pib"},{"application_status":"unknown","audiences":["Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)","School / Kennisinstelling"],"description":"Bent u mkb''er in een technologische onderzoeks- en ontwikkelingssector? Werkt u daarbij samen met partners in andere landen of wilt u dat gaan doen? Dan kunt u mogelijk gebruik maken van Eurostars. Met de subsidie wordt snellere ontwikkeling en groei van kleine bedrijven gestimuleerd.[rvo_custom:eloket:login6-eh3-aanvraag_bekijken]&nbsp;","eligibility":"not_assessed","id":"70c8c42d-be63-45c5-856a-680dcb52cb01","modified":"2026-09-10T12:00:07+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Innovatie, onderzoek en onderwijs"],"title":"Eurostars: subsidie internationale marktgerichte R&D","url":"https://www.rvo.nl/subsidies-financiering/eurostars"},{"application_status":"unknown","audiences":["Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)"],"description":"Het bedrijfsleven heeft de afgelopen 10 jaar veel gebruikgemaakt van het Private Sector Investeringenprogramma (PSI) en voorlopers als PSOM. De PSI-projecten hebben een belangrijke bijdrage geleverd aan economische ontwikkeling en aan armoedebestrijding op alle continenten.","eligibility":"not_assessed","id":"96d678b1-53da-4d97-804a-5e3d2085076e","modified":"2026-06-09T12:10:20+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Internationaal ondernemen","Ontwikkelingssamenwerking"],"title":"Private Sector Investeringsprogramma (PSI)","url":"https://www.rvo.nl/subsidies-financiering/private-sector-investeringsprogramma"},{"application_status":"unknown","audiences":["Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)"],"description":"Bent u bezig met de technische ontwikkeling van een nieuw product, proces of dienst? Of met de klinische ontwikkeling van een medicijn of apparaat? Profiteer dan van het Innovatiekrediet. Zowel mkb''ers als grote bedrijven kunnen van deze overheidsfinanciering gebruikmaken.Doe de Quick Scan&nbsp;","eligibility":"not_assessed","id":"fc4c9323-2b08-479d-a115-73d64cd467fd","modified":"2026-07-15T11:41:14+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Innovatie, onderzoek en onderwijs"],"title":"Innovatiekrediet","url":"https://www.rvo.nl/subsidies-financiering/innovatiekrediet"},{"application_status":"unknown","audiences":["Financier","Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)"],"description":"Met Seed Capital ondersteunen investeerders start-ups met financiering, kennis, netwerk en ervaring. Private, ervaren investeerders brengen expertise en kapitaal in, de overheid verdubbelt hun inleg. Zo&nbsp;ondersteunt de overheid innovatieve ondernemingen bij het verkrijgen van risicokapitaal.[rvo_custom:upri:upri_eh2+_direct_aanvragen][rvo_custom:upri:upri_eh2+_fondsen_beheren]","eligibility":"not_assessed","id":"a44d5eca-4d7d-404c-a9f6-83fdb7b490dd","modified":"2026-08-03T07:00:28+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Innovatie, onderzoek en onderwijs"],"title":"Seed Capital","url":"https://www.rvo.nl/subsidies-financiering/seed-capital"},{"application_status":"unknown","audiences":["Financier","Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)"],"description":"Heeft u als ondernemer risicodragend vermogen nodig? Bijvoorbeeld door snelle groei, een bedrijfsovername, een buy out, expansie in het buitenland of een reorganisatie? Met de regeling Groeifaciliteit krijgt uw financier garanties op achtergestelde leningen en op aandelen van participatiemaatschappijen. Zo trekt de overheid financiers over de streep om bedrijven&nbsp;te helpen.","eligibility":"not_assessed","id":"30e5893a-c908-4baa-bf88-ecb322910ac0","modified":"2025-04-24T13:46:47+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Innovatie, onderzoek en onderwijs"],"title":"Groeifaciliteit","url":"https://www.rvo.nl/subsidies-financiering/groeifaciliteit"},{"application_status":"unknown","audiences":["Financier","Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)"],"description":"Heeft u krediet nodig maar krijgt u niet eenvoudig een (bank)lening of bankgarantie? De overheid maakt dit makkelijker met de Garantie Ondernemingsfinanciering (GO). Uw bank of door de minister aangewezen kredietverstrekker kan zo een 50% Staatsgarantie krijgen op middelgrote en grote leningen en verkleint daarmee haar risico. De Garantie Ondernemingsfinanciering houdt kredietstromen op gang zodat ondernemers kunnen blijven ondernemen.","eligibility":"not_assessed","id":"7ceb0253-9986-4b2b-844f-cf3af1ecf713","modified":"2026-07-13T11:39:36+00:00","sectors":["Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Innovatie, onderzoek en onderwijs"],"title":"Garantie Ondernemingsfinanciering (GO)","url":"https://www.rvo.nl/subsidies-financiering/go"},{"application_status":"unknown","audiences":["Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)","Non-profit / NGO","Producentenorganisatie"],"description":"Wilt u meer weten over de projecten die subsidie kregen in de verschillende aanvraagrondes van de subsidie Stimulering Duurzame Energieproductie (SDE, SDE+)&nbsp;en Stimulering Duurzame Energieproductie&nbsp;en Klimaattransitie&nbsp;(SDE++)? Op deze pagina&nbsp;vindt u feiten en cijfers over deze subsidie&nbsp;op een rij.","eligibility":"not_assessed","id":"674fb601-eade-4710-9f7b-bdf775adbbf7","modified":"2026-09-07T12:23:39+00:00","sectors":["Agrarische sector","Waterstofsector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Woning- en projectinrichting"],"subjects":["Klimaat en energie"],"title":"Feiten en cijfers SDE(+)(+)","url":"https://www.rvo.nl/subsidies-financiering/sde/aanvragen/feiten-en-cijfers"},{"application_status":"unknown","audiences":["Financier","Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)","Non-profit / NGO","Particulier / Vereniging / (Ver)huurder","Producentenorganisatie","School / Kennisinstelling"],"description":"U heeft een investering gedaan die energie bespaart. U heeft de Energie-investeringsaftrek (EIA) aangevraagd en ook al een EIA-verklaring ontvangen. Hoe past u dit&nbsp;nu toe in uw belastingaangifte? Op deze pagina leest u er meer over.","eligibility":"not_assessed","id":"49129edc-9e6c-4199-b6b1-0800744c4bdd","modified":"2026-09-03T09:35:34+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Klimaat en energie"],"title":"Belastingaangifte Energie-investeringsaftrek (EIA)","url":"https://www.rvo.nl/subsidies-financiering/eia/ondernemers/belastingaangifte"},{"application_status":"unknown","audiences":["MKB (ook zzp)"],"description":"Heeft u een aanvraag voor Innovatiekrediet ingediend? Lees hier meer over het proces na uw aanvraag.","eligibility":"not_assessed","id":"1a22e759-0f4c-4d93-975c-beed476ddc1d","modified":"2026-01-05T13:06:20+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Innovatie, onderzoek en onderwijs"],"title":"Innovatiekrediet: Na uw aanvraag","url":"https://www.rvo.nl/subsidies-financiering/innovatiekrediet/na-uw-aanvraag"},{"application_status":"unknown","audiences":["Grootbedrijf","MKB (ook zzp)","Producentenorganisatie"],"description":"Heeft u een voorstel voor een innovatief of milieuvriendelijk bedrijfsmiddel dat nog niet op de Milieulijst staat? Bijvoorbeeld omdat u als leverancier een techniek op de markt wilt brengen, of uw markt wilt verbreden? Laat uw bedrijfsmiddel dan op de Milieulijst zetten voor het belastingvoordeel van de Milieu-investeringsaftrek (MIA) en de Willekeurige afschrijving milieu-investeringen (Vamil).","eligibility":"not_assessed","id":"6cc53a37-84f0-4f34-ac40-97316840d17b","modified":"2026-09-03T09:39:16+00:00","sectors":["Agrarische sector","Waterstofsector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Klimaat en energie"],"title":"Uw bedrijfsmiddel op de Milieulijst","url":"https://www.rvo.nl/subsidies-financiering/mia-vamil/voorstel-milieulijst"},{"application_status":"unknown","audiences":["Overheid","Grootbedrijf","MKB (ook zzp)"],"description":"Hieronder vindt u de meest recente officiële bekendmakingen over de milieu-investeringsaftrek (MIA) en de willekeurige afschrijving milieu-investeringen (Vamil). Waaronder ook de publicaties over het Caribisch gebied.","eligibility":"not_assessed","id":"8778c0b7-f0fb-4e4b-84f8-a72d349d013a","modified":"2026-08-20T10:00:22+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Energiedistributie","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Klimaat en energie"],"title":"Officiële bekendmakingen - MIA\\Vamil","url":"https://www.rvo.nl/subsidies-financiering/mia-vamil/ondernemers/officiele-bekendmakingen"},{"application_status":"unknown","audiences":["Grootbedrijf","MKB (ook zzp)"],"description":"Leveranciers en andere belangstellenden kunnen voorstellen om een vernieuwende milieuvriendelijke techniek op te nemen op de Milieulijst. Hierdoor krijgt een ondernemer die investeert in deze techniek, belastingvoordeel met de Milieu-investeringsaftrek (MIA) en de Willekeurige afschrijving milieu-investeringen (Vamil). Of het voorstel op de lijst komt, hangt af van verschillende criteria.","eligibility":"not_assessed","id":"8610be2e-6565-4d53-9569-68e4f966d27e","modified":"2025-12-30T13:34:53+00:00","sectors":["Agrarische sector","Waterstofsector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Klimaat en energie"],"title":"Criteria voor opname op de Milieulijst","url":"https://www.rvo.nl/subsidies-financiering/mia-vamil/voorstel-milieulijst/criteria-opname-milieulijst"},{"application_status":"unknown","audiences":["Financier","Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)","Producentenorganisatie"],"description":"Wilt u investeren in het verduurzamen van gebouwen? Dan kunt u mogelijk belastingvoordeel krijgen. Dit voordeel geldt voor alle investeringen die op de Milieulijst van de MIA\\Vamil staan. Op deze pagina vindt u voorbeelden van investeringen en specifieke informatie om uw aanvraag voor te bereiden.","eligibility":"not_assessed","id":"e227f57c-906f-4364-b7a8-53f708b9b742","modified":"2026-09-03T09:05:47+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","Medische sector","Metaal(bewerkings)industrie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en projectinrichting"],"subjects":["Klimaat en energie"],"title":"MIA\\Vamil voor investeringen in gebouwen","url":"https://www.rvo.nl/subsidies-financiering/mia-vamil/ondernemers/gebouwde-omgeving"},{"application_status":"unknown","audiences":["Financier","Grootbedrijf","Agrarisch ondernemer","MKB (ook zzp)","Non-profit / NGO","Particulier / Vereniging / (Ver)huurder","Producentenorganisatie","School / Kennisinstelling"],"description":"Investeert u als ondernemer in een milieuvriendelijk bedrijfsmiddel van de Milieulijst? Dan kunt&nbsp;u belastingvoordeel krijgen met MIA\\Vamil. Wilt u weten hoe groot dit voordeel is?&nbsp;Bekijk dan&nbsp;onderstaande rekenvoorbeelden en gebruik de rekentool om uw eigen voordeel te berekenen.\r\n","eligibility":"not_assessed","id":"ffa5e302-9c8f-4107-b99e-3f1f5417c14e","modified":"2026-09-03T08:55:36+00:00","sectors":["Agrarische sector","Biotechnologie","Bosbouw en hout(bewerkings)industrie","Bouw en infrastructuur","Chemie en kunststoffen","Consumentengoederen en detailhandel","Creatieve industrie","Dienstensector","Elektronica-industrie (waaronder HTSM)","Energiesector","Grafische en papierindustrie","ICT","Kleding en textiel","Machine-industrie","Medische sector","Metaal(bewerkings)industrie","Mijnbouw en petrochemie","Milieusector","Onderwijs en opvang","Overheid","Toerisme recreatie en horeca","Transportmiddelenindustrie","Verpakkingsindustrie","Vervoer en logistiek","Voedings- en genotmiddelen","Watersector","Woning- en pro